        category: "accessories",
        price: "$142",
        rating: 5,
        description: "Roomy, refined, and made for daily carry with an elevated profile.",
        badge: "Limited"
      },
      {
        name: "Soft Touch Throw",
        category: "home",
        price: "$58",
        rating: 4,
        description: "A tactile layer for the sofa or bedroom that adds comfort instantly.",
        badge: "Cozy"
      },
      {
        name: "Contour Sunglasses",
        category: "accessories",
        price: "$88",
        rating: 5,
        description: "A minimal frame that sharpens up everyday outfits with subtle attitude.",
        badge: "Trending"
      }
    ];

    const productsEl = document.getElementById("products");
    const filterButtons = document.querySelectorAll(".filter-btn");
    const toast = document.getElementById("toast");

    function stars(count) {
      return "★".repeat(count) + "☆".repeat(5 - count);
    }

    function renderProducts(filter = "all") {
      const visible = filter === "all" ? products : products.filter((product) => product.category === filter);
      productsEl.innerHTML = visible.map((product) => `
        <article class="product-card">
          <div class="product-visual">
            <span class="product-pill">${product.badge}</span>
          </div>
          <div class="product-body">
            <div class="product-meta">
              <div>
                <h3>${product.name}</h3>
                <div class="rating" aria-label="${product.rating} out of 5 stars">${stars(product.rating)}</div>
              </div>
              <div class="price">${product.price}</div>
            </div>
            <p>${product.description}</p>
            <div class="product-actions">
              <button class="add" type="button">Add to cart</button>
              <button class="view" type="button">View details</button>
            </div>
          </div>
        </article>
      `).join("");
    }

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add("show");
      clearTimeout(showToast.timer);
      showToast.timer = setTimeout(() => toast.classList.remove("show"), 1600);
    }

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        filterButtons.forEach((item) => item.classList.remove("active"));
        button.classList.add("active");
        renderProducts(button.dataset.filter);
      });
    });

    productsEl.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button) return;
      showToast(button.classList.contains("add") ? "Added to cart" : "Opening product details");
    });

    document.querySelector(".signup").addEventListener("submit", (event) => {
      event.preventDefault();
      showToast("Thanks for joining");
      event.target.reset();
    });

    const countdown = {
      days: 4,
      hours: 12,
      minutes: 48
    };

    function tickCountdown() {
      countdown.minutes -= 1;
      if (countdown.minutes < 0) {
        countdown.minutes = 59;
        countdown.hours -= 1;
      }
      if (countdown.hours < 0) {
        countdown.hours = 23;
        countdown.days -= 1;
      }

      document.getElementById("days").textContent = String(Math.max(countdown.days, 0)).padStart(2, "0");
      document.getElementById("hours").textContent = String(Math.max(countdown.hours, 0)).padStart(2, "0");
      document.getElementById("minutes").textContent = String(Math.max(countdown.minutes, 0)).padStart(2, "0");
    }

    renderProducts();
    tickCountdown();
    setInterval(tickCountdown, 60000);
  </script>
